) as a LEFT JOIN user on user.id = a.manager)as b LEFT JOIN application_form on b.app_form_id =
application_form.id


union all select b.*,application_form.order_number,application_form.user_id as appUser from (select
a.*,userName from ( select log.*,fin_product.fin_product_name as name,fin_material_number as material_number
from log LEFT JOIN fin_product on log.product_id = fin_product.id where log.vault = fin_product.vault and log.id
