) as z left join user on z.appUser = user.id

SELECT SUM(log_number) as sum,e.product_id,e.vault,name,material_number from (select * from (select b.product_id,b.name,b.material_number,log_number,b.vault,sort from (SELECT log.*,a.name,a.material_number from log LEFT JOIN (select * from product where (id,vault) in (select product_id,vault from log) UNION all select * from fin_product where (id,vault) in (select product_id,vault from log)) as a on log.product_id = a.id and log.vault = a.vault
log.date > #{maps.betweenDate}
#{maps.andDate} > log.date
log.date between #{maps.betweenDate} and #{maps.andDate}
and (name like CONCAT('%',#{maps.str},'%') or material_number like CONCAT('%',#{maps.str},'%'))
(name like CONCAT('%',#{maps.str},'%') or material_number like CONCAT('%',#{maps.str},'%'))
) as b LEFT JOIN application_form on b.app_form_id = application_form.id
application_form.sort=0 and complete_status!=2
application_form.sort=1 and complete_status!=2
) as c) as e GROUP BY product_id,vault,name,material_number limit #{begin},#{size}

select count(*) from ( SELECT count(*) from (select * from (select b.product_id,b.name,b.material_number,log_number,b.vault,sort from (SELECT log.*,a.name,a.material_number from log LEFT JOIN (select * from product where (id,vault) in (select product_id,vault from log) UNION all select * from fin_product where (id,vault) in (select product_id,vault from log)) as a on log.product_id = a.id and log.vault = a.vault
log.date > #{maps.betweenDate}
#{maps.andDate} > log.date
log.date between #{maps.betweenDate} and #{maps.andDate}
and (name like CONCAT('%',#{maps.str},'%') or material_number like CONCAT('%',#{maps.str},'%'))
